svg.script:
/**/
(function() {
  var root = document.querySelector('.a12p11-root');
  if (!root) return;

  function setActive(scene) {
    if (!scene) return;
    root.setAttribute('data-active', scene);

    // Atualiza acessibilidade aria-pressed
    var btns = root.querySelectorAll('[data-target]');
    btns.forEach(function(btn) {
      var isTarget = btn.getAttribute('data-target') === scene;
      if (btn.hasAttribute('aria-pressed')) {
        btn.setAttribute('aria-pressed', isTarget ? 'true' : 'false');
      }
    });
  }

  // Clique em qualquer alvo com data-target (tabs ou hotspots)
  root.addEventListener('click', function(e) {
    var target = e.target.closest('[data-target]');
    if (target) {
      var scene = target.getAttribute('data-target');
      if (scene) setActive(scene);
    }
  });

  // Suporte a teclado (Enter, Espaco e Teclas 1, 2, 3)
  root.addEventListener('keydown', function(e) {
    var target = e.target.closest('[data-target]');
    if (target && (e.key === 'Enter' || e.key === ' ')) {
      e.preventDefault();
      var scene = target.getAttribute('data-target');
      if (scene) setActive(scene);
    }

    if (e.key === '1') setActive('anatomica');
    if (e.key === '2') setActive('obstetrica');
    if (e.key === '3') setActive('diagonalis');
  });
})();
/**/
